tool_input.content:
/**
 * Maps Pi agent session events onto `@aicl/core` stream events.
 *
 * One `prompt()` is one AICL assistant message. Pi may run several turns
 * (model → tools → model) inside it; every turn's content is appended to that
 * one message in order, so the transcript reads as a single answer with its
 * tool cards inline.
 *
 * Pi types are described structurally so this module stays pure and testable
 * without loading the SDK.
 */

import type { FinishReason, Part, StreamEvent, ToolCallPart, Usage } from '@aicl/core';

interface PiToolCall {
  type: 'toolCall';
  id: string;
  name: string;
  arguments: Record<string, unknown>;
}

interface PiAssistantMessage {
  role: 'assistant';
  content: Array<{ type: string } | PiToolCall>;
  stopReason?: string;
  errorMessage?: string;
  usage?: { input?: number; output?: number; cost?: { total?: number } };
}

type PiAssistantEvent =
  | { type: 'text_start' | 'thinking_start' | 'toolcall_start'; contentIndex: number; partial: PiAssistantMessage }
  | { type: 'text_delta' | 'thinking_delta' | 'toolcall_delta'; contentIndex: number; delta: string }
  | { type: 'text_end' | 'thinking_end'; contentIndex: number; content: string }
  | { type: 'toolcall_end'; contentIndex: number; toolCall: PiToolCall }
  | { type: 'start' | 'done' | 'error' };

export type PiEvent =
  | { type: 'agent_start' | 'agent_end' | 'turn_start' | 'turn_end' }
  | { type: 'message_start' | 'message_end'; message: { role: string } }
  | { type: 'message_update'; assistantMessageEvent: PiAssistantEvent }
  | { type: 'tool_execution_start' | 'tool_execution_update'; toolCallId: string }
  | { type: 'tool_execution_end'; toolCallId: string; isError: boolean }
  | { type: string };

export function createPiEventMapper(messageId: string) {
  let next = 0;
  /** Pi content index → AICL part index, for the assistant message in flight. */
  const indexOf = new Map<number, number>();
  const tools = new Map<string, { index: number; part: ToolCallPart }>();
  const usage: Required<Pick<Usage, 'inputTokens' | 'outputTokens'>> & { costUsd: number } = {
    inputTokens: 0,
    outputTokens: 0,
    costUsd: 0,
  };
  let lastStop: string | undefined;
  let lastError: string | undefined;

  const start = (contentIndex: number, part: Part): StreamEvent => {
    const index = next++;
    indexOf.set(contentIndex, index);
    return { type: 'part-start', index, part };
  };

  const setTool = (toolCallId: string, status: ToolCallPart['status']): StreamEvent[] => {
    const tool = tools.get(toolCallId);
    if (!tool) return [];
    tool.part = { ...tool.part, status };
    return [{ type: 'part-end', index: tool.index, part: tool.part }];
  };

  return function map(event: PiEvent): StreamEvent[] {
    switch (event.type) {
      case 'agent_start':
        return [{ type: 'message-start', id: messageId, role: 'assistant' }];

      case 'message_start': {
        if ((event as { message: { role: string } }).message.role === 'assistant') indexOf.clear();
        return [];
      }

      case 'message_update':
        return mapAssistant((event as { assistantMessageEvent: PiAssistantEvent }).assistantMessageEvent);

      case 'message_end': {
        const message = (event as { message: PiAssistantMessage }).message;
        if (message.role !== 'assistant') return [];
        usage.inputTokens += message.usage?.input ?? 0;
        usage.outputTokens += message.usage?.output ?? 0;
        usage.costUsd += message.usage?.cost?.total ?? 0;
        lastStop = message.stopReason;
        lastError = message.errorMessage;
        return [];
      }

      case 'tool_execution_start':
        return setTool((event as { toolCallId: string }).toolCallId, 'running');

      case 'tool_execution_end': {
        const end = event as { toolCallId: string; isError: boolean };
        return setTool(end.toolCallId, end.isError ? 'error' : 'success');
      }

      case 'agent_end':
        if (lastStop === 'error') {
          return [{ type: 'error', error: { message: lastError ?? 'The agent failed.', retryable: true } }];
        }
        return [{ type: 'message-end', finishReason: finishReason(lastStop), usage }];

      default:
        return [];
    }
  };

  function mapAssistant(e: PiAssistantEvent): StreamEvent[] {
    switch (e.type) {
      case 'text_start':
        return [start(e.contentIndex, { type: 'text', text: '' })];
      case 'thinking_start':
        return [start(e.contentIndex, { type: 'reasoning', text: '' })];
      case 'toolcall_start': {
        const call = e.partial.content[e.contentIndex] as Partial<PiToolCall> | undefined;
        return [
          start(e.contentIndex, {
            type: 'tool-call',
            toolCallId: call?.id ?? '',
            name: call?.name ?? 'tool',
            args: {},
            status: 'pending',
          }),
        ];
      }
      case 'text_delta':
      case 'thinking_delta':
      case 'toolcall_delta': {
        const index = indexOf.get(e.contentIndex);
        return index === undefined ? [] : [{ type: 'part-delta', index, delta: e.delta }];
      }
      case 'text_end':
      case 'thinking_end': {
        const index = indexOf.get(e.contentIndex);
        if (index === undefined) return [];
        const part: Part =
          e.type === 'text_end' ? { type: 'text', text: e.content } : { type: 'reasoning', text: e.content };
        return [{ type: 'part-end', index, part }];
      }
      case 'toolcall_end': {
        const index = indexOf.get(e.contentIndex);
        if (index === undefined) return [];
        const part: ToolCallPart = {
          type: 'tool-call',
          toolCallId: e.toolCall.id,
          name: e.toolCall.name,
          args: e.toolCall.arguments,
          argsText: JSON.stringify(e.toolCall.arguments, null, 2),
          status: 'pending',
        };
        tools.set(e.toolCall.id, { index, part });
        return [{ type: 'part-end', index, part }];
      }
      default:
        return [];
    }
  }
}

function finishReason(stop: string | undefined): FinishReason {
  if (stop === 'aborted') return 'aborted';
  if (stop === 'length') return 'length';
  return 'stop';
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ChatController, type ChatTransport, type StreamEvent } from '@aicl/core';
import { createPiEventMapper, type PiEvent } from './pi-mapper.ts';

const call = { type: 'toolCall' as const, id: 'tc1', name: 'scratch_add', arguments: { shapes: [] } };
const assistant = (extra: object = {}) => ({
  role: 'assistant',
  content: [],
  stopReason: 'stop',
  usage: { input: 10, output: 5, cost: { total: 0.01 } },
  ...extra,
});

/** Two turns: thinking + tool call, then the tool runs, then a text answer. */
const twoTurns: PiEvent[] = [
  { type: 'agent_start' },
  { type: 'turn_start' },
  { type: 'message_start', message: { role: 'user' } },
  { type: 'message_start', message: { role: 'assistant' } },
  { type: 'message_update', assistantMessageEvent: { type: 'thinking_start', contentIndex: 0, partial: assistant() } },
  { type: 'message_update', assistantMessageEvent: { type: 'thinking_delta', contentIndex: 0, delta: 'plan' } },
  { type: 'message_update', assistantMessageEvent: { type: 'thinking_end', contentIndex: 0, content: 'plan' } },
  {
    type: 'message_update',
    assistantMessageEvent: { type: 'toolcall_start', contentIndex: 1, partial: assistant({ content: [{ type: 'thinking' }, call] }) },
  },
  { type: 'message_update', assistantMessageEvent: { type: 'toolcall_delta', contentIndex: 1, delta: '{"shapes"' } },
  { type: 'message_update', assistantMessageEvent: { type: 'toolcall_end', contentIndex: 1, toolCall: call } },
  { type: 'message_end', message: assistant({ stopReason: 'toolUse' }) },
  { type: 'tool_execution_start', toolCallId: 'tc1' },
  { type: 'tool_execution_end', toolCallId: 'tc1', isError: false },
  { type: 'turn_end' },
  { type: 'turn_start' },
  { type: 'message_start', message: { role: 'assistant' } },
  { type: 'message_update', assistantMessageEvent: { type: 'text_start', contentIndex: 0, partial: assistant() } },
  { type: 'message_update', assistantMessageEvent: { type: 'text_delta', contentIndex: 0, delta: 'Drew ' } },
  { type: 'message_update', assistantMessageEvent: { type: 'text_delta', contentIndex: 0, delta: 'it.' } },
  { type: 'message_update', assistantMessageEvent: { type: 'text_end', contentIndex: 0, content: 'Drew it.' } },
  { type: 'message_end', message: assistant() },
  { type: 'agent_end' },
];

const mapAll = (events: PiEvent[]): StreamEvent[] => {
  const map = createPiEventMapper('m1');
  return events.flatMap(map);
};

test('turns append to one message; the second turn does not overwrite the first', () => {
  const out = mapAll(twoTurns);
  assert.deepEqual(out[0], { type: 'message-start', id: 'm1', role: 'assistant' });
  const starts = out.filter((e) => e.type === 'part-start').map((e) => (e as { index: number }).index);
  assert.deepEqual(starts, [0, 1, 2], 'text from turn two lands at index 2, not 0');
  const last = out[out.length - 1]!;
  assert.equal(last.type, 'message-end');
  assert.deepEqual((last as { usage: unknown }).usage, { inputTokens: 20, outputTokens: 10, costUsd: 0.02 });
});

test('tool status walks pending → running → success', () => {
  const statuses = mapAll(twoTurns)
    .filter((e) => e.type === 'part-end' && e.part?.type === 'tool-call')
    .map((e) => ((e as { part: { status: string } }).part.status));
  assert.deepEqual(statuses, ['pending', 'running', 'success']);
});

test('a failed run surfaces as an error event, not a clean finish', () => {
  const out = mapAll([
    { type: 'agent_start' },
    { type: 'message_start', message: { role: 'assistant' } },
    { type: 'message_end', message: assistant({ stopReason: 'error', errorMessage: 'rate limited' }) },
    { type: 'agent_end' },
  ]);
  assert.deepEqual(out[out.length - 1], { type: 'error', error: { message: 'rate limited', retryable: true } });
});

test('the mapped stream drives a ChatController to the expected message', async () => {
  const transport: ChatTransport = {
    async *send() {
      yield* mapAll(twoTurns);
    },
  };
  const chat = new ChatController({ transport });
  await chat.send('draw it');
  const reply = chat.messages[1]!;
  assert.equal(chat.state.get().status, 'idle');
  assert.deepEqual(
    reply.parts.map((p) => p.type),
    ['reasoning', 'tool-call', 'text'],
  );
  assert.equal((reply.parts[2] as { text: string }).text, 'Drew it.');
  assert.equal((reply.parts[1] as { status: string }).status, 'success');
});
